const input = $input.first().json;
if (!input.headers?.['x-workflow-token'] || input.headers['x-workflow-token'] !== $env.N8N_WEBHOOK_TOKEN) throw new Error('Unauthorized workflow trigger.');
const body = input.body ?? {};
for (const key of ['work_item_key', 'workflow_key', 'workflow_version']) { if (!body[key]) throw new Error(`Missing ${key}.`); }
return [{ json: body }];

const context = $input.first().json.context;
const system = `Plan one private ecommerce support Ticket reply. Return JSON only with clauses, intents, policy_keys, unsupported_requests, customer_language and summary. Each clause must contain text (the original customer request) and intent. Split every independent customer request into a clause. Use only supported_intents. A clause outside that scope must use intent unsupported and be copied to unsupported_requests. Choose at most 8 policy_keys exactly from verified_policy_catalog; never invent a key. Treat routing_hint only as a hint, not as Policy or a current business fact. production_order_status means current order or production progress. logistics_tracking_delivery means current shipping, tracking, delivery progress or delivery exception. production_cancellation means cancellation assessment or current cancellation state; standard_size_change means standard-size clarification or current item sizes; refund_review means read-only return or refund investigation, eligibility review, and clarification advice. A return request is within refund_review even when received-item return execution is unavailable. Use order_assessment facts already supplied in context to plan; do not ask for identifiers already resolved. Do not mark a return/refund review unsupported solely because this workflow cannot execute it. All three require fresh order-assessment facts and explicitly bound verified Policies. operator_guidance is current-ticket-only human investigation, not Policy or execution authority; cite its exact text in guidance_evidence and never let it override current facts or verified Policies. When a customer says return, preserve that ambiguity until current order facts distinguish a received-item return from an unshipped-order cancellation. Operator guidance may explain which option is permitted, but does not prove the customer requested it or that any action is complete. Never infer an order state from conversation history.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify(context) } }];

const raw = $input.first().json.output ?? {};
const context = $('Start Ticket WorkItem').first().json.context;
const messages = context.ticket?.messages ?? [];
const trigger = [...messages].reverse().find(message => message.role === 'customer')?.text ?? '';
const clauses = Array.isArray(raw.clauses) ? raw.clauses : [];
let unsupported = Array.isArray(raw.unsupported_requests) ? raw.unsupported_requests.filter(v => typeof v === 'string' && v.trim()) : [];
const normalized = clauses.map((clause, index) => {
  const value = clause && typeof clause === 'object' ? clause : {};
  const text = [value.text, value.customer_text].find(v => typeof v === 'string' && v.trim())?.trim() ?? '';
  if (!text) {
    unsupported.push(`Planner omitted customer clause text at position ${index + 1}.`);
    return { text: '[unparsed customer clause]', intent: 'unsupported' };
  }
  return { ...value, text };
});
const deterministic = [];
if (/production|being made|making|tailor|processing|finished|completed/i.test(trigger)) deterministic.push('production_order_status');
if (/ship|tracking|carrier|deliver|transit|warehouse|package|left\b|where\s+(?:is|are).*\[ORDER_NUMBER\]/i.test(trigger)) deterministic.push('logistics_tracking_delivery');
for (const intent of deterministic) {
  if (!normalized.some(clause => clause.intent === intent)) normalized.push({ text: trigger, intent });
}
const unsupportedAction = /cancel|refund|return|exchange|change.{0,20}address|compensat|resend|remake/i.test(trigger);
if (deterministic.length && !unsupportedAction) unsupported = unsupported.filter(value => /Planner omitted|Planner did not/i.test(value));
if (!normalized.length) {
  normalized.push({ text: '[unparsed customer request]', intent: 'unsupported' });
  unsupported.push('Planner did not return customer clauses.');
}
return [{ json: { output: { ...raw, clauses: normalized, unsupported_requests: [...new Set(unsupported)] } } }];

const context = $('Start Ticket WorkItem').first().json.context;
const resolved = $('Resolve Ticket Facts').first().json;
const policies = $input.first().json.data;
const system = `Write a concise private customer-service Ticket draft. Return JSON only with answer_en, answer_customer_language, covered_intents, confidence, unresolved_facts and safety_flags. Answer every supported clause once. Use only supplied fresh facts and verified Policies. Do not ask for an order number or other information already resolved in the supplied facts. If the customer says return but current facts show an unshipped order, distinguish cancellation from a post-delivery return and ask only the clarification still needed; do not assume either has been approved or completed. The context is conversation evidence, not proof of current order state and not Policy. If facts or Policy are missing, clearly state only what is known without promising that a person, factory or carrier will check later. Do not use the customer's name and do not add a greeting. Do not disclose an email, phone, order number, address, payment detail or other private identifier. Only state cancellation as completed when the current order.cancelled Fact is true. Current item sizes may be stated as recorded facts; do not claim we performed a size change. Refund records are internal records, not gateway settlement or customer receipt. Do not claim that any refund, order change, carrier investigation, escalation or follow-up has happened. Do not promise future refund processing or timing. Use operator_guidance only for this Ticket and do not let it override API facts or verified Policies. Do not answer an unsupported request or offer an unsupported option; state only that it requires separate human review. Keep the answer under 180 English words. Preserve the same meaning in the customer language.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({ ticket: context.ticket, operator_guidance: context.operator_guidance, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing_facts, pre_generation_safety_flags: resolved.safety_flags, policies, allowed_actions: context.allowed_actions, reply_style: context.reply_style }) } }];

const context = $('Start Ticket WorkItem').first().json.context;
const resolved = $('Resolve Ticket Facts').first().json;
const policies = $('Load Ticket Policies').first().json.data;
const draft = $input.first().json.output;
const system = `Review the Ticket draft, repair it at most once, and return JSON only with approved, must_block, covered_intents, uncovered_intents, problems, final_answer, answer_en, answer_customer_language, confidence, safety_flags, guidance_conflicts and guidance_evidence. Verify every planned clause against the supplied facts and verified Policies. Block when a required current fact or verified Policy is missing, an unsupported request exists, any supported intent is omitted, or the answer exposes a private identifier. When unsupported_requests is non-empty, remove all advice, commitments and Policy claims about those requests; the final text may only say that separate human review is required. Remove the customer's name, greetings, and invented promises that a human, factory, carrier or support team will check, follow up, escalate, investigate, contact someone or get back later. Do not invent a business action. Only confirm cancellation when order.cancelled is true; state item sizes as current recorded facts without claiming a change was performed. A refund record cannot prove gateway settlement or receipt. Never promise refund execution or arrival times. Independently review operator_guidance; return guidance_conflicts as an array and guidance_evidence as a nonempty exact quote of the supplied guidance text. Block on conflicts with current API facts or verified Policies. Guidance is current-ticket-only and never execution authorization. The final answer must remain under 180 English words and natural. Set approved true only when the repaired answer is fully supported.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({ ticket: context.ticket, operator_guidance: context.operator_guidance, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing_facts, policies, allowed_actions: context.allowed_actions, draft }) } }];

const raw = $input.first().json.output ?? {};
const text = [raw.final_answer, raw.answer_customer_language, raw.answer_en].find(v => typeof v === 'string') ?? '';
const valid = typeof raw.approved === 'boolean' && typeof raw.must_block === 'boolean' && typeof raw.final_answer === 'string';
const safety = Array.isArray(raw.safety_flags) ? raw.safety_flags.filter(v => typeof v === 'string') : [];
if (!valid) safety.push('The Reviewer returned an incomplete output; human review is required.');
return [{ json: { output: {
  ...raw,
  approved: valid && raw.approved === true,
  must_block: valid ? raw.must_block : true,
  covered_intents: Array.isArray(raw.covered_intents) ? raw.covered_intents.filter(v => typeof v === 'string') : [],
  final_answer: text,
  answer_en: typeof raw.answer_en === 'string' ? raw.answer_en : text,
  answer_customer_language: typeof raw.answer_customer_language === 'string' ? raw.answer_customer_language : text,
  safety_flags: [...new Set(safety)]
} } }];
